
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_xc_th_fco_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_xc_th_fco", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.940821441510878e+00, -4.849343442791586e+00, -4.719393433383167e+00, -4.536257130464652e+00, -4.281648690097611e+00, -3.935784359289406e+00, -3.484057680921930e+00, -2.931695004809537e+00, -2.325873823344080e+00, -1.760292173104907e+00, -1.261180544885976e+00, -9.183853037682784e-01, -8.353412674582160e-01, -7.232457152319167e-01, -5.864203015198504e-01, -4.571197784122848e-01, -3.532633966452849e-01, -2.770973870134390e-01, -2.227342230668490e-01, -1.601144315621984e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


